fun <T, R> List<T>.mapChecked70(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
sealed class Outcome71 {
    data class Success(val payload: String) : Outcome71()
    data object Failure : Outcome71()
}

fun describe71(outcome: Outcome71): String = when (outcome) {
    is Outcome71.Success -> outcome.payload
    Outcome71.Failure -> "failed"
}
